const articles = [
 {id:'hay',icon:'🌾',cat:'feeding',title:'Heu: die tägliche Basis',summary:'Warum hochwertiges Heu immer verfügbar sein sollte.',body:`<p>Hochwertiges, staubarmes Heu sollte jederzeit verfügbar sein. Es liefert Rohfaser und unterstützt die natürliche Abnutzung der ständig wachsenden Backenzähne.</p><h3>Im Alltag</h3><ul><li>Frisch anbieten und feuchtes oder verschmutztes Heu entfernen.</li><li>Trocken und luftig lagern, nicht luftdicht feucht einschließen.</li><li>Bei plötzlichem Rückgang der Heuaufnahme zeitnah tierärztlich abklären lassen.</li></ul>`},
 {id:'pellets',icon:'🥣',cat:'feeding',title:'Pellets und Futterwechsel',summary:'Futter nicht abrupt wechseln und Zusammensetzung prüfen.',body:`<p>Nutze ein geeignetes, gleichbleibendes Alleinfutter für Chinchillas und halte dich an die Herstellerempfehlung sowie tierärztliche Hinweise. Bunte Mischungen mit vielen süßen Bestandteilen sind häufig ungeeignet.</p><h3>Wichtig</h3><ul><li>Futterumstellungen langsam und aufmerksam durchführen.</li><li>Keine Süßigkeiten, Honigsticks oder zuckerreichen Snacks als Routine.</li><li>Appetitverlust ist bei Chinchillas ernst zu nehmen.</li></ul>`},
 {id:'water',icon:'💧',cat:'feeding',title:'Frisches Wasser',summary:'Täglich wechseln und Trinkgefäß gründlich kontrollieren.',body:`<p>Stelle immer sauberes Trinkwasser bereit. Wechsle es täglich und prüfe Flasche oder Napf auf Funktion, Verschmutzung und sichere Befestigung.</p><h3>Beobachten</h3><p>Eine deutliche Änderung der Trinkmenge kann ein Hinweis auf ein Problem sein. Bei weiteren Symptomen oder anhaltender Veränderung frage eine Tierarztpraxis.</p>`},
 {id:'unsafe',icon:'🚫',cat:'feeding',title:'Leckerlis und ungeeignete Nahrung',summary:'Weniger ist mehr: süße und feuchte Snacks vermeiden.',body:`<p>Chinchillas haben einen empfindlichen Verdauungstrakt. Vermeide zuckerreiche, fettreiche und feuchte Lebensmittel sowie unbekannte Pflanzen oder Zweige.</p><h3>Vorsicht</h3><ul><li>Keine Schokolade, Süßigkeiten oder menschlichen Knabbereien.</li><li>Ob frische Kräuter, Blätter oder Zweige geeignet sind, hängt von Art, Herkunft und Trocknung ab.</li><li>Im Zweifel nicht verfüttern und fachkundig nachfragen.</li></ul>`},
 {id:'temperature',icon:'🌡️',cat:'housing',title:'Hitze und Raumklima',summary:'Temperatur messen, Schatten und Luftaustausch sicherstellen.',body:`<p>Chinchillas sind hitzeempfindlich. Ein Thermometer auf Tierhöhe hilft, den tatsächlichen Raumwert zu kennen. Direkte Sonne und schlecht belüftete, warme Räume sind zu vermeiden.</p><h3>Praktische Vorsorge</h3><ul><li>Temperatur am Gehege messen, auch an warmen Tagen und abends.</li><li>Für Schatten, sichere Luftzirkulation und kühle Rückzugsorte sorgen.</li><li>Keine kalten Gegenstände verwenden, an denen Tiere festfrieren oder sich verletzen können.</li><li>Bei Hitzestress sofort tierärztliche Hilfe einholen.</li></ul><p>Die App gibt nur eine Orientierung. Die tatsächliche Belastung hängt auch von Luftfeuchtigkeit, Luftstrom, Gesundheit und Verhalten ab.</p>`},
 {id:'housing',icon:'🏡',cat:'housing',title:'Gehege und Rückzugsorte',summary:'Hoch, sicher, gut belüftet und mit mehreren Verstecken.',body:`<p>Das Gehege sollte großzügig, sicher und gut belüftet sein, mit stabilen Ebenen, Verstecken und geeigneten Beschäftigungsmöglichkeiten. Gitterabstände, Materialien und Sprunghöhen müssen Verletzungen verhindern.</p><h3>Regelmäßig prüfen</h3><ul><li>Keine scharfen Kanten, losen Drähte oder giftigen Materialien.</li><li>Rückzugsorte und mehrere sichere Ebenen anbieten.</li><li>Einrichtung so platzieren, dass Stürze aus großer Höhe vermieden werden.</li></ul>`},
 {id:'dust',icon:'🛁',cat:'housing',title:'Sandbad richtig anbieten',summary:'Geeigneter Chinchillasand, keine Badesalze oder Duftzusätze.',body:`<p>Das Sandbad dient der Fellpflege. Verwende dafür geeigneten Chinchillasand und halte das Gefäß sauber und trocken. Staubige, parfümierte oder ungeeignete Bademischungen sind keine gute Wahl.</p><p>Wie lange und wie häufig das Bad angeboten wird, sollte sich nach Tier, Umgebung und fachkundiger Empfehlung richten. Entferne es, wenn es als Toilette genutzt wird oder stark verschmutzt ist.</p>`},
 {id:'companions',icon:'🐭',cat:'behavior',title:'Sozialleben und Zusammenführung',summary:'Chinchillas sind soziale Tiere und brauchen passende Gesellschaft.',body:`<p>Chinchillas sollten grundsätzlich nicht ohne triftigen Grund allein gehalten werden. Eine Vergesellschaftung muss sorgfältig geplant werden und kann Zeit brauchen.</p><h3>Vorbereitung</h3><ul><li>Geschlecht sicher bestimmen lassen, um Nachwuchs zu vermeiden.</li><li>Quarantäne und Gesundheitscheck neuer Tiere mit einer fachkundigen Praxis besprechen.</li><li>Langsame, sichere Zusammenführung mit Ausweichmöglichkeiten planen.</li><li>Bei heftigen Kämpfen trennen und fachkundige Hilfe einholen.</li></ul>`},
 {id:'droppings',icon:'🔎',cat:'health',title:'Kot und Verdauung beobachten',summary:'Menge, Form und Appetit sind wichtige Alltagssignale.',body:`<p>Kontrolliere täglich grob, ob Kotmenge und Aussehen dem üblichen Muster entsprechen. Deutlich weniger oder kein Kot, Futterverweigerung, aufgeblähter Bauch oder starke Teilnahmslosigkeit können dringend sein.</p><p>Bei solchen Veränderungen nicht abwarten oder selbst behandeln, sondern rasch eine chinchilla-erfahrene Tierarztpraxis kontaktieren.</p>`},
 {id:'weight',icon:'⚖️',cat:'health',title:'Gewicht sinnvoll dokumentieren',summary:'Regelmäßig und möglichst unter ähnlichen Bedingungen wiegen.',body:`<p>Ein Gewichtstagebuch kann Trends sichtbar machen, ersetzt aber keine Untersuchung. Wiege möglichst mit derselben Waage und zu einer ähnlichen Tageszeit. Notiere auffällige Verhaltensänderungen.</p><h3>Wann reagieren?</h3><p>Ungeklärte Gewichtsabnahme, fehlender Appetit oder veränderte Ausscheidungen sollten zeitnah tierärztlich abgeklärt werden. Die App setzt keine medizinischen Grenzwerte für dein Tier fest.</p>`},
 {id:'vet',icon:'🩺',cat:'health',title:'Tierarzt und Notfallzeichen',summary:'Früh reagieren und eine geeignete Praxis vorab suchen.',body:`<p>Suche möglichst vorab eine Praxis mit Erfahrung mit Chinchillas und notiere Kontakt sowie Notdienst. Chinchillas können Erkrankungen lange verbergen.</p><h3>Dringend abklären</h3><ul><li>Futterverweigerung oder deutlich weniger Kot.</li><li>Auffällige Atmung, Hecheln, Schwäche oder Kollaps.</li><li>Starkes Speicheln, Gleichgewichtsprobleme oder Verletzungen.</li><li>Plötzliche deutliche Verhaltensänderungen.</li></ul><p>Bei akuten oder schweren Symptomen sofort tierärztliche Hilfe suchen.</p>`},
 {id:'enrichment',icon:'🪵',cat:'behavior',title:'Beschäftigung ohne Risiko',summary:'Nagen, erkunden, verstecken und springen können.',body:`<p>Biete sichere Nagematerialien, stabile Ebenen, Tunnel und Verstecke an. Prüfe Spielzeug regelmäßig auf Splitter, lose Teile, giftige Beschichtungen und verschluckbare Bestandteile.</p><p>Beschäftigung sollte Wahlmöglichkeiten geben und jederzeit einen Rückzug erlauben. Beobachte, was dein Tier tatsächlich nutzt, statt die Einrichtung ständig zu verändern.</p>`},
 {id:'cleaning',icon:'🧹',cat:'housing',title:'Sauberkeit ohne Stress',summary:'Verschmutzte Stellen täglich entfernen und gründlich reinigen.',body:`<p>Entferne feuchte oder stark verschmutzte Stellen regelmäßig. Verwende für die Reinigung tiergeeignete Mittel, spüle bei Bedarf sorgfältig nach und lasse alles vollständig trocknen.</p><p>Eine komplette Reinigung sollte so organisiert sein, dass die Tiere sicher untergebracht sind und nicht unnötig gestresst werden. Beobachte Gerüche als möglichen Hinweis auf feuchte Stellen oder Gesundheitsprobleme.</p>`},
 {id:'handling',icon:'🤲',cat:'behavior',title:'Vertrauen aufbauen',summary:'Geduld, Routine und freiwilliger Kontakt sind entscheidend.',body:`<p>Setze dich ruhig in die Nähe, sprich leise und lass das Tier selbst entscheiden, ob es näherkommen möchte. Biete die Hand zum Beschnuppern an und vermeide Greifen von oben.</p><p>Chinchillas sind keine Kuscheltiere auf Abruf. Respektiere Rückzug und individuelle Grenzen. Kurze positive Begegnungen sind besser als erzwungener Kontakt.</p>`}
];
function go(view){const target=$('#view-'+view);if(!target)return;$$('.view').forEach(v=>v.classList.toggle('active',v===target));$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.go===view || (view==='settings'&&n.dataset.go==='settings')));window.scrollTo({top:0,behavior:'smooth'});if(view==='animals')renderAnimals();if(view==='knowledge')renderArticles();if(view==='planner')renderPlanner();if(view==='routine')renderRoutine();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b){e.preventDefault();go(b.dataset.go);}});
function applyLanguage(){
document.documentElement.lang=state.lang==='zh'?'zh-CN':state.lang;
$$('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;if(tr(k))el.textContent=tr(k)});
$('#knowledgeSearch').placeholder=tr('searchPlaceholder');
$('#knowledgeFilter').options[0].textContent=tr('allTopics');$('#knowledgeFilter').options[1].textContent=tr('feeding');$('#knowledgeFilter').options[2].textContent=tr('housing');$('#knowledgeFilter').options[3].textContent=tr('health');$('#knowledgeFilter').options[4].textContent=tr('behavior');
$('#languageBtn').textContent=({de:'DE',en:'EN',zh:'中文'})[state.lang]||'DE';
$('#languageSetting').textContent=({de:'Deutsch',en:'English',zh:'中文'})[state.lang]||'Deutsch';
const placeholders={
animalName:{de:'z. B. Flocke',en:'e.g. Snowflake',zh:'例如：雪球'},
weightValue:{de:'z. B. 520',en:'e.g. 520',zh:'例如：520'},
weightNote:{de:'z. B. vor dem Füttern',en:'e.g. before feeding',zh:'例如：喂食前'},
supplyInput:{de:'z. B. Heu nachkaufen',en:'e.g. buy more hay',zh:'例如：补充干草'},
generalNotes:{de:'Beobachtungen, Fragen für den Tierarzt, Einkaufsideen …',en:'Observations, questions for the vet, shopping ideas…',zh:'观察记录、兽医问题、采购想法…'},
userName:{de:'Wie dürfen wir dich nennen?',en:'What should we call you?',zh:'您希望我们如何称呼您？'},
knowledgeSearch:{de:'Artikel suchen …',en:'Search articles…',zh:'搜索文章…'}
};
Object.entries(placeholders).forEach(([id,vals])=>{const el=document.getElementById(id);if(el)el.placeholder=vals[state.lang]||vals.de;});
const staticText = {
'CHINCHILLA-PROFILE':{en:'CHINCHILLA PROFILES',zh:'龙猫档案'},'GEWICHTSVERLAUF':{en:'WEIGHT HISTORY',zh:'体重记录'},'WOHLFÜHL-CHECK':{en:'WELLBEING CHECK',zh:'舒适度检查'},'TAG FÜR TAG':{en:'DAY BY DAY',zh:'每日护理'},'GUT ORGANISIERT':{en:'STAY ORGANIZED',zh:'井井有条'},'WISSEN, DAS GUT TUT':{en:'HELPFUL KNOWLEDGE',zh:'实用知识'},'DEIN BEREICH':{en:'YOUR SPACE',zh:'个人空间'},'NEUES PROFIL':{en:'NEW PROFILE',zh:'新建档案'},'CHINCHICARE WISSEN':{en:'CHINCHICARE KNOWLEDGE',zh:'ChinchiCare 知识'}
};
$$('.eyebrow').forEach(el=>{const raw=el.dataset.staticOriginal||(el.textContent||'').trim();if(!el.dataset.staticOriginal)el.dataset.staticOriginal=raw;const translated=staticText[raw];if(translated)el.textContent=state.lang==='de'?raw:(translated[state.lang]||raw);});
const sex=$('#animalSex');if(sex&&sex.options.length>=3){sex.options[0].textContent=tr('unknown');sex.options[1].textContent=tr('female');sex.options[2].textContent=tr('male');}
renderAll();
}
function toggleLanguage(){state.lang=({de:'en',en:'zh',zh:'de'})[state.lang]||'de';save();applyLanguage();}
$('#languageBtn').addEventListener('click',toggleLanguage);$('#languageSetting').addEventListener('click',toggleLanguage);
$('#themeBtn').addEventListener('click',()=>{state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);$('#themeBtn').textContent=state.dark?'☾':'☼';save();});
function renderDate(){const d=new Date();$('#todayDate').textContent=d.toLocaleDateString(state.lang==='de'?'de-DE':state.lang==='zh'?'zh-CN':'en-GB',{weekday:'short',day:'numeric',month:'short'});}
function renderRoutine(){if(state.routineDate!==today()){state.routineDate=today();state.routine={};localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}const renderInto=(el)=>{el.innerHTML='';routineItems.forEach(([id,emoji,key])=>{const label=document.createElement('label');label.className='routine-item'+(state.routine[id]?' done':'');label.innerHTML=`<input type="checkbox" ${state.routine[id]?'checked':''}><span class="routine-emoji">${emoji}</span><span>${esc(tr(key))}</span>`;const input=$('input',label);input.addEventListener('change',()=>{state.routine[id]=input.checked;save();});el.appendChild(label);});};renderInto($('#homeRoutine'));renderInto($('#fullRoutine'));const done=routineItems.filter(([id])=>state.routine[id]).length;const pct=Math.round(done/routineItems.length*100);$('#careProgress').textContent=pct;$('#routineProgressText').textContent=pct+' %';$('#routineProgressBar').style.width=pct+'%';}
$('#resetRoutine').addEventListener('click',()=>{state.routine={};save();toast(tr('saved'));});
function ageText(date){if(!date)return tr('ageUnknown');const birth=new Date(date+'T00:00:00');if(Number.isNaN(birth.getTime()))return tr('ageUnknown');let months=(new Date().getFullYear()-birth.getFullYear())*12+new Date().getMonth()-birth.getMonth();if(new Date().getDate()<birth.getDate())months--;if(months<0)return tr('ageUnknown');const years=Math.floor(months/12),m=months%12;return `${years?years+' '+tr('years')+' ':''}${m} ${tr('months')}`;}
function renderAnimals(){const list=$('#animalList');list.innerHTML='';state.animals.forEach(a=>{const card=document.createElement('article');card.className='animal-card';const photo=a.photo?`style="background-image:url('${a.photo}')"`:'';card.innerHTML=`<div class="animal-photo" ${photo}>${a.photo?'': '🐭'}</div><div class="animal-card-body"><h3>${esc(a.name)}</h3><p>${esc(tr(a.sex==='female'?'female':a.sex==='male'?'male':'unknown'))} · ${esc(ageText(a.birth))}</p><p>${esc(a.notes||tr('noWeights'))}</p><div class="animal-actions"><button class="secondary-btn" data-weight="${a.id}">⚖️ ${esc(tr('addWeight').replace(' →',''))}</button><button class="danger-btn" data-delete-animal="${a.id}">×</button></div></div>`;list.appendChild(card);});$('#emptyAnimals').classList.toggle('hidden',state.animals.length>0);$('#animalList').classList.toggle('hidden',state.animals.length===0);const sel=$('#weightAnimal');const prev=sel.value;sel.innerHTML=state.animals.map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');if(state.animals.some(a=>a.id===prev))sel.value=prev;$('#weightForm button[type=submit]').disabled=!state.animals.length;renderWeightHistory();renderHomeMetrics();}
function renderHomeMetrics(){const last=state.climate[0];$('#homeTemp').textContent=last?last.temp:'--';$('#homeTempNote').textContent=last?new Date(last.at).toLocaleString(state.lang==='de'?'de-DE':state.lang==='zh'?'zh-CN':'en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):tr('tempHint');const w=state.weights.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0];$('#homeWeight').textContent=w?w.value:'--';$('#homeWeightNote').textContent=w?`${state.animals.find(a=>a.id===w.animalId)?.name||''} · ${w.date}`:tr('weightHint');}
$('#addAnimalBtn').addEventListener('click',openAnimalDialog);$('#emptyAddAnimal').addEventListener('click',openAnimalDialog);function openAnimalDialog(){if($('#animalDialog').showModal)$('#animalDialog').showModal();else $('#animalDialog').setAttribute('open','');}
$('#closeAnimalDialog').addEventListener('click',()=>$('#animalDialog').close());$('#cancelAnimal').addEventListener('click',()=>$('#animalDialog').close());
$('#animalForm').addEventListener('submit',async e=>{e.preventDefault();const name=$('#animalName').value.trim();if(!name)return;let photo='';const file=$('#animalPhoto').files[0];if(file){if(file.size>900000){toast(tr('photoTooLarge'));return;}try{photo=await fileToDataURL(file);}catch{toast(tr('photoReadError'));return;}}state.animals.push({id:uid(),name,sex:$('#animalSex').value,birth:$('#animalBirth').value,photo,notes:$('#animalNotes').value.trim(),createdAt:new Date().toISOString()});$('#animalForm').reset();$('#animalDialog').close();save();toast(tr('profileSaved'));});
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas'),max=480,scale=Math.min(1,max/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.78));};img.onerror=reject;img.src=r.result;};r.onerror=reject;r.readAsDataURL(file);});}
$('#animalList').addEventListener('click',e=>{const w=e.target.closest('[data-weight]');if(w){$('#weightAnimal').value=w.dataset.weight;$('#weightValue').focus();$('#weightDate').value=today();toast(tr('addWeight'));}const del=e.target.closest('[data-delete-animal]');if(del&&confirm(tr('confirmAnimalDelete'))){state.animals=state.animals.filter(a=>a.id!==del.dataset.deleteAnimal);state.weights=state.weights.filter(a=>a.animalId!==del.dataset.deleteAnimal);save();}});
$('#weightDate').value=today();
$('#weightForm').addEventListener('submit',e=>{e.preventDefault();if(!state.animals.length){toast(tr('noAnimalSelected'));return;}state.weights.push({id:uid(),animalId:$('#weightAnimal').value,value:Number($('#weightValue').value),date:$('#weightDate').value||today(),note:$('#weightNote').value.trim()});state.weights.sort((a,b)=>b.date.localeCompare(a.date));$('#weightValue').value='';$('#weightNote').value='';save();toast(tr('weightRecorded'));});
function renderWeightHistory(){const box=$('#weightHistory');box.innerHTML='';const rows=state.weights.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,20);if(!rows.length){box.className='weight-history empty-inline';box.textContent=tr('noWeights');return;}box.className='weight-history';rows.forEach(w=>{const animal=state.animals.find(a=>a.id===w.animalId);const row=document.createElement('div');row.className='history-row';row.innerHTML=`<span><strong>${esc(animal?.name||'')}</strong><br><small>${esc(w.date)}${w.note?' · '+esc(w.note):''}</small></span><strong>${w.value} g</strong><button aria-label="Eintrag löschen" data-delete-weight="${w.id}">×</button>`;box.appendChild(row);});}
$('#weightHistory').addEventListener('click',e=>{const b=e.target.closest('[data-delete-weight]');if(b){state.weights=state.weights.filter(w=>w.id!==b.dataset.deleteWeight);save();}});
$('#tempRange').addEventListener('input',()=>{state.temp=Number($('#tempRange').value);$('#tempDisplay').textContent=state.temp;updateClimateAssessment(false);});$('#humidityRange').addEventListener('input',()=>{state.humidity=Number($('#humidityRange').value);$('#humidityDisplay').textContent=state.humidity;updateClimateAssessment(false);});
$('#climateTime').value=dtLocal();
function updateClimateAssessment(saved=false){const t=Number($('#tempRange').value),h=Number($('#humidityRange').value);let title,advice,emoji;if(t>=26){title=tr('tempDanger');advice=tr('tempDangerAdvice');emoji='🥵';}else if(t>=23){title=tr('tempCaution');advice=tr('tempCautionAdvice');emoji='🌤️';}else{title=tr('tempCool');advice=tr('tempCoolAdvice');emoji='🌿';}if(h<30)advice+=' '+tr('humidityLow');if(h>70)advice+=' '+tr('humidityHigh');$('#climateTitle').textContent=title;$('#climateAdvice').textContent=advice;$('#climateEmoji').textContent=emoji;$('#tempDisplay').textContent=t;$('#humidityDisplay').textContent=h;}
$('#climateForm').addEventListener('submit',e=>{e.preventDefault();const t=Number($('#tempRange').value),h=Number($('#humidityRange').value);state.temp=t;state.humidity=h;state.climate.unshift({id:uid(),temp:t,humidity:h,at:$('#climateTime').value?new Date($('#climateTime').value).toISOString():new Date().toISOString()});state.climate=state.climate.slice(0,50);$('#climateTime').value=dtLocal();save();toast(tr('tempRecorded'));});
function renderClimate(){const latest=state.climate[0];if(latest){$('#tempRange').value=latest.temp;$('#humidityRange').value=latest.humidity;}else{$('#tempRange').value=state.temp;$('#humidityRange').value=state.humidity;}$('#tempDisplay').textContent=$('#tempRange').value;$('#humidityDisplay').textContent=$('#humidityRange').value;updateClimateAssessment();const box=$('#climateHistory');box.innerHTML='';if(!state.climate.length){box.className='climate-history empty-inline';box.textContent=tr('noClimateData');return;}box.className='climate-history';state.climate.slice(0,12).forEach(m=>{const row=document.createElement('div');row.className='climate-history-row';row.innerHTML=`<span>${new Date(m.at).toLocaleString(state.lang==='de'?'de-DE':state.lang==='zh'?'zh-CN':'en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</span><strong>${m.temp} °C · ${m.humidity} %</strong>`;box.appendChild(row);});}
function renderPlanner(){const box=$('#weeklyPlan');box.innerHTML='';weeklyItems.forEach((it,i)=>{const [day,key,description]=it;const dayNames={de:{Mo:'Mo',Di:'Di',Mi:'Mi'},en:{Mo:'Mon',Di:'Tue',Mi:'Wed'},zh:{Mo:'周一',Di:'周二',Mi:'周三'}};const descriptions={zh:{'Gehege und Einrichtung gründlich reinigen':'彻底清洁笼舍和内部设施','Gewicht zur ähnlichen Tageszeit kontrollieren':'尽量在每天相近的时间称重','Heu, Futter und Einstreu prüfen':'检查干草、食物和垫料'}};const shownDay=(dayNames[state.lang]||dayNames.de)[day]||day;const shownDescription=((descriptions[state.lang]||{})[description])||description;const row=document.createElement('div');row.className='weekly-day';const checked=!!state.week[i];row.innerHTML=`<div class="day-badge">${shownDay}</div><div><label style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" ${checked?'checked':''} data-week="${i}" style="accent-color:#56866b;margin-top:2px"><span><strong>${esc(tr(key))}</strong><p>${esc(shownDescription)}</p></span></label></div>`;box.appendChild(row);});$('#supplyList').innerHTML='';if(!state.supplies.length){$('#supplyList').innerHTML=`<p class="muted">${esc(tr('emptySupplies'))}</p>`;}state.supplies.forEach(item=>{const row=document.createElement('label');row.className='supply-item';row.innerHTML=`<input type="checkbox" ${item.done?'checked':''}><span style="${item.done?'text-decoration:line-through;opacity:.6':''}">${esc(item.text)}</span><button type="button" class="remove" aria-label="${esc(tr('remove'))}">×</button>`;row.querySelector('input').addEventListener('change',e=>{item.done=e.target.checked;save();});row.querySelector('button').addEventListener('click',()=>{state.supplies=state.supplies.filter(x=>x.id!==item.id);save();});$('#supplyList').appendChild(row);});$('#generalNotes').value=state.notes||'';}
$('#weeklyPlan').addEventListener('change',e=>{const i=e.target.dataset.week;if(i!==undefined){state.week[i]=e.target.checked;save();}});
$('#supplyForm').addEventListener('submit',e=>{e.preventDefault();const text=$('#supplyInput').value.trim();if(!text)return;state.supplies.push({id:uid(),text,done:false});$('#supplyInput').value='';save();});
$('#generalNotes').addEventListener('input',()=>{state.notes=$('#generalNotes').value;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{}});
function renderArticles(){const query=$('#knowledgeSearch').value.toLowerCase().trim(),cat=$('#knowledgeFilter').value;const box=$('#articleGrid');box.innerHTML='';const filtered=articles.filter(a=>(cat==='all'||a.cat===cat)&&(`${a.title} ${a.summary} ${a.body}`.toLowerCase().includes(query)));if(!filtered.length){box.innerHTML=`<p class="muted">${esc(tr('searchNoResults'))}</p>`;return;}filtered.forEach(original=>{const a=localizedArticle(original);const card=document.createElement('article');card.className='article-card';card.innerHTML=`<div class="article-icon">${a.icon}</div><span class="category">${esc(tr(a.cat))}</span><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><button class="text-btn" data-article="${a.id}">${esc(tr('articleRead'))} →</button>`;box.appendChild(card);});}
$('#knowledgeSearch').addEventListener('input',renderArticles);$('#knowledgeFilter').addEventListener('change',renderArticles);
$('#articleGrid').addEventListener('click',e=>{const b=e.target.closest('[data-article]');if(!b)return;const original=articles.find(x=>x.id===b.dataset.article);if(!original)return;const a=localizedArticle(original);$('#articleDetail').innerHTML=`<div class="article-detail-icon">${a.icon}</div><span class="eyebrow">${esc(tr(a.cat))}</span><h1 style="font-size:32px">${esc(a.title)}</h1><p class="muted">${esc(a.summary)}</p><div class="article-detail-content">${a.body}<p><em>${esc(tr('articleDisclaimer'))}</em></p></div>`;$('#articleDialog').showModal();});
$('#closeArticleDialog').addEventListener('click',()=>$('#articleDialog').close());
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=tr('exportName');document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast(tr('exported'));}
$('#exportData').addEventListener('click',exportData);$('#exportData2').addEventListener('click',exportData);
$('#clearData').addEventListener('click',()=>{if(confirm(tr('confirmDelete'))){localStorage.removeItem(STORAGE_KEY);state=defaultState();document.body.classList.remove('dark');save();applyLanguage();toast(tr('deleted'));}});
$('#userName').addEventListener('change',()=>{state.name=$('#userName').value.trim();save();});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}


const zhArticleData = {"hay": ["干草：每日饮食基础", "为什么应始终提供优质干草。", "<p>应随时提供优质、低粉尘的干草。干草提供粗纤维，并有助于自然磨耗不断生长的臼齿。</p><h3>日常护理</h3><ul><li>每天提供新鲜干草，并清除潮湿或弄脏的干草。</li><li>存放在干燥、通风处，不要将潮湿干草密封保存。</li><li>如果龙猫突然明显减少进食干草，请及时咨询兽医。</li></ul>"], "pellets": ["颗粒饲料与换粮", "不要突然更换食物，并注意检查配方。", "<p>选择适合龙猫且配方稳定的全价饲料，并遵循生产商建议及兽医意见。含有许多甜味成分的彩色混合饲料通常并不合适。</p><h3>重要提示</h3><ul><li>换粮时应缓慢进行，并仔细观察。</li><li>不要经常喂糖果、蜂蜜棒或高糖零食。</li><li>龙猫食欲下降需要认真对待。</li></ul>"], "water": ["新鲜饮水", "每天更换，并仔细检查饮水器具。", "<p>始终提供干净的饮用水。每天换水，并检查水瓶或水碗是否正常、干净且固定牢靠。</p><h3>观察变化</h3><p>饮水量明显变化可能提示健康问题。如果同时出现其他症状或变化持续存在，请咨询兽医。</p>"], "unsafe": ["零食与不适合的食物", "少即是多：避免含糖和潮湿的零食。", "<p>龙猫的消化系统较为敏感。避免高糖、高脂肪和潮湿的食物，以及来源不明的植物或树枝。</p><h3>请注意</h3><ul><li>不要喂巧克力、糖果或人类零食。</li><li>新鲜香草、叶子或树枝是否适合，取决于种类、来源和干燥方式。</li><li>如有疑问，请勿喂食，并向专业人士咨询。</li></ul>"], "temperature": ["高温与室内环境", "测量温度，确保遮阴和空气流通。", "<p>龙猫对高温很敏感。在动物活动高度放置温度计，有助于了解真实室温。应避免阳光直射以及温暖、通风不良的房间。</p><h3>实用预防措施</h3><ul><li>在笼舍附近测量温度，天气炎热时以及傍晚也要检查。</li><li>提供遮阴、安全的空气流通和凉爽的休息处。</li><li>不要使用可能导致动物冻粘或受伤的冰冷物品。</li><li>出现中暑迹象时，立即寻求兽医帮助。</li></ul><p>本应用仅提供参考。实际热负担还取决于湿度、气流、健康状况和行为。</p>"], "housing": ["笼舍与躲藏处", "空间充足、安全、通风良好，并设有多个躲藏点。", "<p>笼舍应宽敞、安全且通风良好，并配有稳固的平台、躲藏处和适当的活动设施。栏杆间距、材料和跳跃高度都应避免造成伤害。</p><h3>定期检查</h3><ul><li>避免锋利边缘、松动的金属丝或有毒材料。</li><li>提供躲藏处和多个安全的平台。</li><li>合理布置设施，避免从高处跌落。</li></ul>"], "dust": ["正确提供沙浴", "使用适合龙猫的浴沙，不要添加浴盐或香料。", "<p>沙浴用于护理毛发。请使用适合龙猫的浴沙，并保持容器清洁、干燥。不要使用有香味、粉尘过多或不适合的浴沙混合物。</p><p>沙浴的时长和频率应根据动物、环境及专业建议来决定。如果龙猫把沙浴当作厕所或浴沙明显变脏，请将其移除。</p>"], "companions": ["社交与合笼", "龙猫是群居动物，需要合适的同伴。", "<p>原则上，不应在没有充分理由的情况下单独饲养龙猫。引入新同伴需要仔细计划，也可能需要较长时间。</p><h3>提前准备</h3><ul><li>请专业人士确认性别，以避免意外繁殖。</li><li>与有经验的兽医讨论新动物的隔离和健康检查。</li><li>规划缓慢且安全的合笼过程，并提供可躲避的空间。</li><li>如果发生激烈打斗，应分开动物并寻求专业帮助。</li></ul>"], "droppings": ["观察粪便与消化", "粪便数量、形态和食欲是重要的日常信号。", "<p>每天简单检查粪便数量和外观是否与平时一致。粪便明显减少或停止排出、拒绝进食、腹部胀大或精神极度萎靡，都可能是紧急情况。</p><p>出现这些变化时不要等待或自行治疗，应尽快联系有龙猫诊疗经验的兽医。</p>"], "weight": ["科学记录体重", "定期称重，并尽量保持相似条件。", "<p>体重记录有助于观察趋势，但不能替代兽医检查。尽量使用同一台秤，并在每天相近的时间称重。也要记录明显的行为变化。</p><h3>何时需要采取行动？</h3><p>原因不明的体重下降、食欲不振或排泄变化，应尽快由兽医检查。本应用不会为你的动物设定医学诊断阈值。</p>"], "vet": ["兽医与紧急症状", "提前寻找合适的诊所，并及时采取行动。", "<p>建议提前寻找有龙猫诊疗经验的兽医，并保存联系方式和急诊信息。龙猫可能会长时间隐藏疾病迹象。</p><h3>需要尽快就医的情况</h3><ul><li>拒绝进食或粪便明显减少。</li><li>呼吸异常、喘气、虚弱或倒下。</li><li>大量流口水、失去平衡或受伤。</li><li>行为突然发生明显变化。</li></ul><p>出现急性或严重症状时，请立即寻求兽医帮助。</p>"], "enrichment": ["安全的活动与玩耍", "提供啃咬、探索、躲藏和跳跃的机会。", "<p>提供安全的啃咬材料、稳固的平台、隧道和躲藏处。定期检查玩具是否有碎片、松动部件、有毒涂层或可能被吞下的小零件。</p><p>活动设施应让动物有选择，并随时可以躲避。观察动物实际喜欢使用什么，不要频繁改变环境。</p>"], "cleaning": ["清洁且减少压力", "每天清理脏污区域，并定期彻底清洁。", "<p>定期清除潮湿或严重脏污的垫料。使用适合动物的清洁用品，必要时彻底冲洗，并让所有物品完全干燥。</p><p>彻底清洁时，应确保动物待在安全的地方，避免不必要的压力。异味也可能提示潮湿区域或健康问题。</p>"], "handling": ["建立信任", "耐心、规律和自愿接触很重要。", "<p>安静地坐在附近，轻声说话，让龙猫自行决定是否靠近。可以伸出手让它闻一闻，避免从上方突然抓取。</p><p>龙猫并不是随时都可以抱的宠物。请尊重它们躲避和表达界限的需要。短暂、积极的互动比强迫接触更好。</p>"]};
function localizedArticle(a){if(state.lang==='zh'&&zhArticleData[a.id]){const z=zhArticleData[a.id];return {...a,title:z[0],summary:z[1],body:z[2]};}return a;}
